/* Admin-only classification management. Every write is authenticated and revision checked. */
let jobTaxonomyAvailable=false,jobTaxonomyLoaded=false,jobQuota=null,jobManagerGeneration=0;
async function loadJobTaxonomy(force=false){
 if(!jobTaxonomyLoaded||force){try{const result=await api('/api/job-taxonomy');if(!sessionUser)return;ZYClassification.configure(result);jobQuota=result.remaining;jobTaxonomyAvailable=true}catch{jobTaxonomyAvailable=false}jobTaxonomyLoaded=true}
 const inputs=[...orders.filter(o=>orderState(o)==='ready').flatMap(o=>ZYClassification.itemsFor(orderPublication(o).order,'order')),...workers.flatMap(w=>ZYClassification.itemsFor(w,'worker'))];await ZYClassification.bind(inputs);
}
function jobManagerAllowed(){return sessionUser?.role==='admin'&&!sessionUser?.readOnly}
function classificationUnits(){return [...orders.filter(o=>orderState(o)==='ready').map(o=>({kind:'order',record:orderPublication(o).order})),...workers.map(w=>({kind:'worker',record:w}))]}
function classificationCoverage(){const units=classificationUnits(),jobs=units.filter(x=>x.kind==='order'),history=units.filter(x=>x.kind==='worker').flatMap(x=>ZYMatching.profileFor(x.record,'worker').history),jobRows=jobs.map(x=>ZYMatching.profileFor(x.record));const count=rows=>({total:rows.length,classified:rows.filter(r=>r.major&&r.major!=='other').length,other:rows.filter(r=>r.major==='other'&&r.evidence).length,unclassified:rows.filter(r=>!r.major||r.major==='other'&&!r.evidence).length});return {jobs:count(jobRows),history:count(history)}}
async function openClassificationManager(){if(!jobManagerAllowed())return;const owner=sessionUser.id;await loadWorkers();await loadJobTaxonomy(true);if(sessionUser?.id!==owner)return;renderClassificationManager();$('#modal').showModal()}
function renderClassificationManager(){
 if(!jobManagerAllowed())return;const coverage=classificationCoverage(),dict=ZYClassification.dictionary.filter(s=>!s.merged_into),units=classificationUnits(),references=id=>{let jobs=0,people=0;for(const u of units){const p=ZYMatching.profileFor(u.record,u.kind),rows=u.kind==='order'?[p]:p.history;if(rows.some(r=>r.subcategory_id===id))u.kind==='order'?jobs++:people++}return {jobs,people}},majorOptions=selected=>ZYJobCategories.majors.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${m.label}</option>`).join('');
 const unresolved=units.flatMap(u=>ZYClassification.itemsFor(u.record,u.kind).map(item=>({...item,classification:item.kind==='history'?ZYMatching.profileFor(u.record,'worker').history.find(r=>r.index===item.index):item.kind==='order'?ZYMatching.profileFor(u.record):item.kind==='intent'?ZYMatching.profileFor(u.record,'worker').intents.find(r=>r.index===item.index):null}))).filter(x=>x.classification?.major==='other');window.jobUnresolved=unresolved;
 $('#modal').innerHTML=`<h2>岗位分类管理</h2><p>仅管理分类，不修改公司单或劳工业务字段。</p>${!jobTaxonomyAvailable?'<p class="note">共享分类服务尚未部署，当前使用本地规则。回填和分类管理暂不可用。</p>':''}<div class="classification-coverage"><div><b>可发布公司单</b><p><span>已归类</span> <span data-user-content>${coverage.jobs.classified}</span> · <span>其他</span> <span data-user-content>${coverage.jobs.other}</span> · <span>未归类</span> <span data-user-content>${coverage.jobs.unclassified}</span></p></div><div><b>劳工工作经历</b><p><span>已归类</span> <span data-user-content>${coverage.history.classified}</span> · <span>其他</span> <span data-user-content>${coverage.history.other}</span> · <span>未归类</span> <span data-user-content>${coverage.history.unclassified}</span></p></div></div><p><span>剩余归类额度</span> <b data-user-content>${jobQuota??'—'}</b></p><div class="actions"><button class="primary" id="job-backfill-start" ${jobTaxonomyAvailable?'':'disabled'} onclick="backfillClassifications()">归类全部未归类数据</button><button onclick="downloadJobTitles()">导出职位清单</button><button onclick="$('#modal').close()">关闭</button></div><p id="job-backfill-progress" role="status"></p><h3>共享细类词表</h3><div class="classification-scroll"><table class="classification-table"><thead><tr><th>细类名称</th><th>大类</th><th>别名</th><th>状态</th><th>公司单 / 劳工</th><th>操作</th></tr></thead><tbody>${dict.map(s=>{const n=references(s.id);return `<tr data-subcategory="${esc(s.id)}"><td><input data-name value="${esc(s.name)}" aria-label="细类名称" data-user-content></td><td><select data-major aria-label="大类">${majorOptions(s.major)}</select></td><td><input data-aliases value="${esc((s.aliases||[]).join('、'))}" aria-label="别名" data-user-content></td><td><span class="${s.status==='new'?'badge draft':'badge'}">${s.status==='new'?'新增':'已确认'}</span></td><td data-user-content>${n.jobs} / ${n.people}</td><td><button ${jobTaxonomyAvailable?'':'disabled'} onclick="saveSubcategory(${jsValue(s.id)},this)">确认 / 保存</button><button ${jobTaxonomyAvailable?'':'disabled'} onclick="mergeSubcategoryDialog(${jsValue(s.id)})">合并</button></td></tr>`}).join('')}</tbody></table></div>${unresolved.length?`<h3>其他或未归类</h3><div class="classification-scroll"><table class="classification-table"><tbody>${unresolved.map((x,i)=>`<tr><td data-user-content>${esc(x.input.title||x.input.position||x.input.text||'—')}</td><td><select id="job-assign-${i}" aria-label="选择细类">${dict.map(s=>`<option value="${esc(s.id)}" data-user-content>${esc(s.name)}</option>`).join('')}</select></td><td><button ${jobTaxonomyAvailable?'':'disabled'} onclick="assignJobClassification(${i})">人工指定</button></td></tr>`).join('')}</tbody></table></div>`:''}`;
}
async function manageJobClassification(operation,data){if(!jobManagerAllowed()||!jobTaxonomyAvailable)return;const owner=sessionUser.id;try{const result=await api('/api/job-classification-admin',{method:'POST',body:{operation,data}});if(sessionUser?.id!==owner)return;ZYClassification.configure(result);await loadJobTaxonomy(true);matchState.cache.clear();renderClassificationManager();if(view==='match')renderMatchPage()}catch(e){toast(e.message)}}
function saveSubcategory(id,button){const row=button.closest('tr');manageJobClassification('update',{id,name:row.querySelector('[data-name]').value,major:row.querySelector('[data-major]').value,aliases:row.querySelector('[data-aliases]').value.split(/[、，,]/).map(x=>x.trim()).filter(Boolean),status:'active'})}
function mergeSubcategoryDialog(id){const target=ZYClassification.dictionary.filter(s=>s.id!==id&&!s.merged_into);const box=document.createElement('div');box.className='note job-merge';box.innerHTML=`<label>合并到<select>${target.map(s=>`<option value="${esc(s.id)}" data-user-content>${esc(s.name)}</option>`).join('')}</select></label><button>确认合并</button><button>取消</button>`;box.querySelectorAll('button')[0].onclick=()=>manageJobClassification('merge',{id,target:box.querySelector('select').value});box.querySelectorAll('button')[1].onclick=()=>box.remove();$('#modal').prepend(box)}
async function assignJobClassification(i){const item=window.jobUnresolved[i],text=Object.values(item.input).find(x=>String(x).trim());if(!text)return toast('职位或经历为空，请先补充资料');await manageJobClassification('assign',{text_hash:await ZYClassification.textHash(item.kind,item.input),kind:item.kind,evidence:String(text).slice(0,2000),subcategory_id:$('#job-assign-'+i).value})}
function downloadJobTitles(){const titles=[...new Set(orders.map(o=>orderPublication(o).order.title).filter(Boolean))].sort(),data=JSON.stringify({exportedAt:new Date().toISOString(),titles},null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='job-titles-'+ZYTime.todayKey()+'.json';a.click();URL.revokeObjectURL(url)}
async function backfillClassifications(){
 if(!jobManagerAllowed()||!jobTaxonomyAvailable)return;const owner=sessionUser.id,generation=++jobManagerGeneration,button=$('#job-backfill-start');button.disabled=true;
 try{const sourceOrders=await api('/api/orders');await loadWorkers();const units=[...sourceOrders.orders.filter(o=>orderState(o)==='ready').map(o=>({kind:'order',record:orderPublication(o).order})),...workers.map(w=>({kind:'worker',record:{...w}}))],all=units.flatMap(u=>ZYClassification.itemsFor(u.record,u.kind)),unique=[...new Map(all.filter(x=>x.kind==='order'?x.input.title.trim()||x.input.workContent.trim():x.kind==='history'?x.input.position.trim()||x.input.duties.trim():x.input.text.trim()).map(x=>[ZYClassification.canonical(x.kind,x.input),x])).values()];await ZYClassification.bind(unique);const pending=unique.filter(x=>!ZYClassification.cached(x.kind,x.input));let completed=unique.length-pending.length;
  const progress=()=>{const node=$('#job-backfill-progress');if(node)node.textContent=ZYI18n.translate('已完成 {done} / 共 {total}').replace('{done}',completed).replace('{total}',unique.length)};progress();
  for(let i=0;i<pending.length;i+=20){if(sessionUser?.id!==owner||generation!==jobManagerGeneration)return;const items=pending.slice(i,i+20),response=await api('/api/job-classification-batch',{method:'POST',body:{items}});if(sessionUser?.id!==owner||generation!==jobManagerGeneration)return;ZYClassification.configure(response.taxonomy||{});await ZYClassification.bind(unique);completed+=response.items.filter(x=>x.result).length;progress();if(response.items.some(x=>!x.result))throw Error('部分归类失败，已完成结果保留，可再次继续')}
  if(sessionUser?.id!==owner||generation!==jobManagerGeneration)return;
  // Apply only cached metadata in bounded batches. An edit conflict stops rather than overwrites business fields.
  for(let i=0;i<units.length;i+=50){const chunk=units.slice(i,i+50),orderPatches=[],workerPatches=[];for(const u of chunk){const rows=ZYClassification.itemsFor(u.record,u.kind).map(item=>({...ZYClassification.cached(item.kind,item.input),index:item.index,kind:item.kind})).filter(r=>r.major),profile=u.kind==='order'?rows.find(r=>r.kind==='order'):{intents:rows.filter(r=>r.kind==='intent'),history:rows.filter(r=>r.kind==='history'),certificates:rows.filter(r=>r.kind==='certificate')};if(!profile||!rows.length)continue;const patch={id:u.record.id,profile:{...profile,version:2,sourceHash:ZYMatching.sourceHash(u.record,u.kind),by:rows.some(r=>r.by==='user')?'user':'ai',at:new Date().toISOString()}};if(u.kind==='order')orderPatches.push(patch);else workerPatches.push({...patch,version:u.record._version})}
   if(!orderPatches.length&&!workerPatches.length)continue;if(sessionUser?.id!==owner||generation!==jobManagerGeneration)return;const current=await api('/api/orders');if(JSON.stringify(current.orders.map(o=>[o.id,ZYMatching.sourceHash(orderPublication(o).order,'order')]))!==JSON.stringify(sourceOrders.orders.map(o=>[o.id,ZYMatching.sourceHash(orderPublication(o).order,'order')])))throw Error('公司单已修改，请重新回填');await api('/api/job-profile-backfill',{method:'POST',body:{orders:orderPatches,workers:workerPatches,revision:current.revision}});
  }
  if(sessionUser?.id!==owner)return;await performSync();await loadJobTaxonomy(true);renderClassificationManager();toast('分类回填完成')
 }catch(e){toast(e.message)}finally{if(button.isConnected)button.disabled=false}
}
window.ZYClassAdmin={reset(){jobManagerGeneration++;jobTaxonomyAvailable=false;jobTaxonomyLoaded=false;jobQuota=null;window.jobUnresolved=[];ZYClassification.reset()}};
